    describeAppTool: (input) => runSafely(() => describeApp(input)),
    showAppsTool: (input) => runSafely(() => showApps(input)),
    saveQueryTool: (input) => runSafely(() => saveQuery(input)),
    listQueriesTool: (input) => runSafely(() => listQueries(input)),
    getQueryTool: (input) => runSafely(() => getQuery(input)),
    runSavedQueryTool: (input) => runSafely(() => runSavedQuery(input)),
    deleteQueryTool: (input) => runSafely(() => deleteQuery(input))
